New Row.code:
// Insert a row into a SQL Server table.
insert(
  'users',
  { name: 'Elodie', email: 'elodie@example.org', age: 31 },
  { writeSql: true }
);

Update Row.code:
// Update a row with a raw SQL statement.
// sql() has no parameter binding, so build the query from state and
// escape single quotes in string values yourself.
sql(state => ({
  query: `UPDATE users SET email = '${String(state.data.email).replace(/'/g, "''")}' WHERE id = '${String(state.data.id).replace(/'/g, "''")}';`,
  // Query options go under `options`.
  options: { writeSql: true },
}));

Find Row.code:
// Look up a single value from a row matched by an equality filter.
// findValue() resolves to the value itself (not state), so await it inside fn().
fn(async state => {
  state.data.userId = await findValue({
    uuid: 'id',
    relation: 'users',
    where: { email: state.data.email }, // values are escaped for you
  })(state);
  return state;
});

Find Row via Custom Query.code:
// Run a custom SELECT returning a single row.
// sql() has no parameter binding: escape single quotes in values yourself.
// The rows are written to state.response.rows.
sql(state => ({
  query: `SELECT TOP 1 * FROM users WHERE email = '${String(state.data.email).replace(/'/g, "''")}';`,
}));

Find Rows via Custom Query.code:
// Run a custom SELECT returning many rows.
// The rows are written to state.response.rows.
sql({
  query: "SELECT id, name, email FROM users WHERE created_at > '2026-01-01' ORDER BY id;",
});
